    H, W, X, P, Q = t[:5]
    S = [t[5 + i * W: 5 + (i + 1) * W] for i in range(H)]
    start = frozenset([(P - 1, Q - 1)])
    seen = {start}
    stack = [start]
    best = S[P - 1][Q - 1]
    while stack:
        cur = stack.pop()
        T = sum(S[r][c] for r, c in cur)
        if T > best:
            best = T
        frontier = set()
        for (r, c) in cur:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and (nr, nc) not in cur:
                    # absorb only if strength < T / X, i.e. S * X < T
                    if S[nr][nc] * X < T:
                        frontier.add((nr, nc))
        for f in frontier:
            ns = cur | {f}
            if ns not in seen:
                seen.add(ns)
                stack.append(ns)
    return str(best)
